spec.expr:
sort_desc(
  max_over_time(
    (
      sum by(endpoint, method) (
        increase(
          finpos_http_requests_total{
            endpoint!~"/api/v1/metrics|/api/ping",
            job="backend"
          }[1m]
        )
      )
    )[30m:]
  )
) > 15

sort_desc(
  max_over_time(
    (
      histogram_quantile(
        0.95,
        sum by(method, endpoint, le) (
          rate(
            finpos_http_request_duration_seconds_bucket{
              job="backend",
              endpoint!~"/api/v1/metrics|/api/ping",
              endpoint!~".*dashboard.*"
            }[1m]
          )
        )
      )
    )[30m:]
  )
) > 1

sort_desc(
  (
    max_over_time(
      (
        histogram_quantile(
          0.95,
          sum by(method, endpoint, le) (
            rate(
              finpos_http_request_duration_seconds_bucket{
                job="backend",
                endpoint!~"/api/v1/metrics|/api/ping"
              }[1m]
            )
          )
        )
      )[30m:]
    ) > 1
  )
  and
  (
    max_over_time(
      (
        sum by(method, endpoint) (
          increase(
            finpos_http_requests_total{
              job="backend",
              endpoint!~"/api/v1/metrics|/api/ping"
            }[1m]
          )
        )
      )[30m:]
    ) > 15
  )
)
